
/* ── js/idcard-actions-core-state.js ── */

// ID Card Actions - Core State Sub-module
// Contains: Global state, table ID, API helpers, checkbox state/selection, filter query builder
// Split from: idcard-actions-core.js

(function() {
'use strict';

// ==========================================
// GLOBAL STATE
// ==========================================
window.IDCardApp = window.IDCardApp || {};

// ==========================================
// TABLE ID HELPER
// ==========================================
function getTableId() {
    return typeof TABLE_ID !== 'undefined' ? TABLE_ID : (window.IDCardApp?.tableId || null);
}

// Expose on IDCardApp namespace
window.IDCardApp.getTableId = getTableId;

// ==========================================
// EXPOSE UTILS FUNCTIONS TO IDCardApp
// (utils.js must be loaded before this file)
// ==========================================
if (typeof getCSRFToken === 'function') {
    window.IDCardApp.getCSRFToken = getCSRFToken;
}
if (typeof showToast === 'function') {
    window.IDCardApp.showToast = showToast;
}
if (typeof showProgressToast === 'function') {
    window.IDCardApp.showProgressToast = showProgressToast;
}
if (typeof showDownloadComplete === 'function') {
    window.IDCardApp.showDownloadComplete = showDownloadComplete;
}
if (typeof hideToast === 'function') {
    window.IDCardApp.hideProgressToast = hideToast;
}

// ==========================================
// API CALL HELPER (delegates to core/api.js ApiClient)
// ==========================================

function apiCall(url, method, data = null) {
    // Delegate to centralized ApiClient from core/api.js
    if (typeof ApiClient !== 'undefined') {
        return ApiClient.request(url, method, data);
    }
    // Fallback if ApiClient not loaded yet
    const options = {
        method: method,
        headers: {
            'Content-Type': 'application/json',
            'X-CSRFToken': getCSRFToken()
        }
    };
    if (data) options.body = JSON.stringify(data);
    return fetch(url, options).then(r => r.ok ? r.json() : r.json().catch(() => ({})).then(d => { throw new Error(d.message || 'Request failed'); }));
}

// Expose on IDCardApp namespace
window.IDCardApp.apiCall = apiCall;

// ==========================================
// CHECKBOX FUNCTIONALITY
// ==========================================

// Track last clicked checkbox for Shift+Click range selection
let lastClickedCheckboxIndex = null;

// Function to get current row checkboxes (live query)
function getRowCheckboxes() {
    return document.querySelectorAll(".rowCheckbox");
}

function getSelectedCardIds() {
    const checked = document.querySelectorAll('.rowCheckbox:checked');
    return [...checked].map(cb => cb.closest('tr').getAttribute('data-card-id'));
}

// Get all visible card IDs from current list
function getAllVisibleCardIds() {
    const allRows = document.querySelectorAll('#cardsTableBody tr[data-card-id]');
    return [...allRows].map(row => row.getAttribute('data-card-id')).filter(id => id);
}

// Get card IDs - selected if any, otherwise all visible
function getCardIdsForAction() {
    // Use the DB-aware getter so Select All checkbox includes all 
    // database cards, not just the visible 100
    const selectedIds = (typeof getSelectedCardIdsWithDbSelect === 'function')
        ? getSelectedCardIdsWithDbSelect()
        : getSelectedCardIds();
    return selectedIds.length > 0 ? selectedIds : getAllVisibleCardIds();
}

// ==========================================
// CACHED TOOLBAR BUTTON REFS
// Populated once by _cacheToolbarButtons(), called from initCoreModule().
// ==========================================
var _cachedSingleBtns = null;   // editBtn*, viewBtn*
var _cachedMultiBtns  = null;   // deleteBtn*, verifyBtn*, approveBtn*, etc.
var _cachedAddBtn = null;
var _cachedUploadXlsxBtn = null;
var _cachedDeletePermanentBtn = null;

function _cacheToolbarButtons() {
    _cachedSingleBtns = document.querySelectorAll('[id^="editBtn"], [id^="viewBtn"]');
    _cachedMultiBtns  = document.querySelectorAll('[id^="deleteBtn"], [id^="verifyBtn"], [id^="approveBtn"], [id^="disapproveBtn"], [id^="unapprovedBtn"], [id^="retrieveBtn"], [id^="unverifyBtn"], #downloadCardBtn, #printSelectedBtn');
    _cachedAddBtn = document.getElementById('addBtn');
    _cachedUploadXlsxBtn = document.getElementById('uploadXlsxBtn');
    _cachedDeletePermanentBtn = document.getElementById('deletePermanentBtnP');
}

// Update button states when checkboxes change
function updateButtonStates() {
    const rowCheckboxes = getRowCheckboxes();
    const checkedBoxes = [...rowCheckboxes].filter(cb => cb.checked);
    const singleSelected = checkedBoxes.length === 1;
    const anySelected = checkedBoxes.length >= 1;
    const noneSelected = checkedBoxes.length === 0;
    
    // No-selection buttons (Add, Upload XLSX) - disabled when any row is selected
    if (_cachedAddBtn) _cachedAddBtn.disabled = anySelected;
    if (_cachedUploadXlsxBtn) _cachedUploadXlsxBtn.disabled = anySelected;
    
    // Single select buttons (Edit, View) — use cached refs
    if (_cachedSingleBtns) {
        _cachedSingleBtns.forEach(btn => { btn.disabled = !singleSelected; });
    }
    
    // Multi select buttons — use cached refs
    if (_cachedMultiBtns) {
        _cachedMultiBtns.forEach(btn => { btn.disabled = !anySelected; });
    }
    
    // Delete Permanent button (Pool list only)
    if (_cachedDeletePermanentBtn) _cachedDeletePermanentBtn.disabled = !anySelected;

    // Bridge selection state to Alpine for reactive UI bindings
    if (typeof window.alpineUpdateSelection === 'function') {
        window.alpineUpdateSelection(getSelectedCardIds());
    }
}

function initCheckboxes() {
    const selectAll = document.getElementById("selectAll");
    
    // Select All checkbox — when checked, selects ALL cards in the database (not just loaded rows)
    if (selectAll) {
        selectAll.addEventListener("change", async function() {
            const rowCheckboxes = getRowCheckboxes();

            if (this.checked) {
                // Check all visible row checkboxes
                rowCheckboxes.forEach(cb => {
                    cb.checked = true;
                    const row = cb.closest('tr');
                    if (row) row.classList.add('selected');
                });

                // Fetch ALL card IDs from the database via API
                const tableId = window.IDCardApp.tableId;
                if (tableId) {
                    try {
                        const qs = _buildFilterQS();
                        const data = await ApiClient.get('/api/table/' + tableId + '/cards/all-ids/?' + qs);
                        if (data.success && data.card_ids) {
                            window.IDCardApp.allDbCardIds = data.card_ids;
                            showToast('Selected all ' + data.total_count + ' cards');
                        }
                    } catch (err) {
                        console.error('Error fetching all card IDs:', err);
                    }
                }
            } else {
                // Uncheck all visible row checkboxes
                rowCheckboxes.forEach(cb => {
                    cb.checked = false;
                    const row = cb.closest('tr');
                    if (row) row.classList.remove('selected');
                });
                // Clear DB-wide selection
                window.IDCardApp.allDbCardIds = null;
            }

            updateButtonStates();
        });
    }
    
    // Individual row checkboxes - use event delegation
    const tableBody = document.getElementById('cardsTableBody');
    if (tableBody) {
        // Handle Shift+Click for range selection
        tableBody.addEventListener('click', function(e) {
            if (e.target.classList.contains('rowCheckbox')) {
                const rowCheckboxes = [...getRowCheckboxes()];
                const currentIndex = rowCheckboxes.indexOf(e.target);
                
                if (e.shiftKey && lastClickedCheckboxIndex !== null && currentIndex !== lastClickedCheckboxIndex) {
                    // Shift+Click: Range selection
                    e.preventDefault(); // Prevent default checkbox behavior
                    
                    const start = Math.min(lastClickedCheckboxIndex, currentIndex);
                    const end = Math.max(lastClickedCheckboxIndex, currentIndex);
                    
                    // Check all checkboxes in range (from anchor to current, inclusive)
                    for (let i = start; i <= end; i++) {
                        if (rowCheckboxes[i]) {
                            rowCheckboxes[i].checked = true;
                            // Sync .selected class
                            const row = rowCheckboxes[i].closest('tr');
                            if (row) row.classList.add('selected');
                        }
                    }
                    
                    // Trigger change event for button state update
                    updateButtonStates();
                    
                    // Don't update lastClickedCheckboxIndex for shift+click 
                    // so user can continue selecting ranges from the original anchor
                } else {
                    // Normal click (without Shift): Toggle this checkbox and set as anchor
                    // Update last clicked index - this becomes the anchor for Shift+Click
                    lastClickedCheckboxIndex = currentIndex;
                    
                    // Also uncheck selectAll if unchecking a checkbox
                    if (!e.target.checked && selectAll) {
                        selectAll.checked = false;
                    }
                }
            }
        });
        
        // Handle checkbox state changes
        tableBody.addEventListener('change', function(e) {
            if (e.target.classList.contains('rowCheckbox')) {
                // Sync .selected class with checkbox state
                const row = e.target.closest('tr');
                if (row) {
                    if (e.target.checked) row.classList.add('selected');
                    else row.classList.remove('selected');
                }
                const rowCheckboxes = getRowCheckboxes();
                if (!e.target.checked) {
                    selectAll.checked = false;
                    // Also clear DB-wide selection if any checkbox is unchecked
                    window.IDCardApp.allDbCardIds = null;
                } else if ([...rowCheckboxes].every(c => c.checked)) {
                    selectAll.checked = true;
                }
                updateButtonStates();
            }
        });
    }
    
    // Reset last clicked index when page changes or data reloads
    window.IDCardApp.resetShiftClickIndex = function() {
        lastClickedCheckboxIndex = null;
    };
    
    // Initial button state
    updateButtonStates();
}

// Helper: build filter query string from current active filters
function _buildFilterQS() {
    const params = new URLSearchParams();
    const currentStatus = window.IDCardApp.currentStatus || new URLSearchParams(window.location.search).get('status') || 'pending';
    params.set('status', currentStatus);
    // Search
    const searchInput = document.getElementById('searchInput');
    if (searchInput && searchInput.value.trim()) params.set('search', searchInput.value.trim());
    // Class
    if (IDCardApp.currentClassFilter) params.set('class', IDCardApp.currentClassFilter);
    // Section
    if (IDCardApp.currentSectionFilter) params.set('section', IDCardApp.currentSectionFilter);
    // Image sort filter
    if (IDCardApp._activeImageSort) {
        if (IDCardApp._activeImageSort.column) params.set('image_column', IDCardApp._activeImageSort.column);
        if (IDCardApp._activeImageSort.condition) params.set('image_condition', IDCardApp._activeImageSort.condition);
    }
    // DateTime range (download list)
    const fromDate = document.getElementById('fromDateFilter');
    const toDate = document.getElementById('toDateFilter');
    if (fromDate && fromDate.value) params.set('from', fromDate.value);
    if (toDate && toDate.value) params.set('to', toDate.value);
    return params.toString();
}

// Select All Database functionality
function initSelectAllDbButton() {
    const selectAllDbBtn = document.getElementById('selectAllDbBtn');
    if (!selectAllDbBtn) return;
    
    selectAllDbBtn.addEventListener('click', async function() {
        const tableId = window.IDCardApp.tableId;
        
        if (!tableId) {
            showToast('Table ID not found', false);
            return;
        }
        
        // If already active, deselect all
        if (this.classList.contains('active')) {
            this.classList.remove('active');
            window.IDCardApp.allDbCardIds = null;
            
            // Uncheck all visible checkboxes
            const selectAll = document.getElementById("selectAll");
            if (selectAll) {
                selectAll.checked = false;
                selectAll.dispatchEvent(new Event('change', { bubbles: true }));
            }
            showToast('Selection cleared');
            return;
        }
        
        // Show loading state
        const originalContent = this.innerHTML;
        this.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Loading...';
        this.disabled = true;
        
        try {
            const qs = _buildFilterQS();
            const data = await ApiClient.get(`/api/table/${tableId}/cards/all-ids/?${qs}`);
            
            if (data.success && data.card_ids) {
                // Store all card IDs globally
                window.IDCardApp.allDbCardIds = data.card_ids;
                
                // Mark button as active
                this.classList.add('active');
                
                // Check all visible checkboxes
                const selectAll = document.getElementById("selectAll");
                if (selectAll) {
                    selectAll.checked = true;
                    const rowCheckboxes = getRowCheckboxes();
                    rowCheckboxes.forEach(cb => {
                        cb.checked = true;
                    });
                }
                
                updateButtonStates();
                showToast(`Selected all ${data.total_count} cards`);
            } else {
                showToast(data.message || 'Failed to get card IDs', false);
            }
        } catch (error) {
            console.error('Error fetching all card IDs:', error);
            showToast('Error fetching card IDs', false);
        } finally {
            this.innerHTML = originalContent;
            this.disabled = false;
        }
    });
}

// Override getSelectedCardIds to use all DB IDs when Select All DB is active
const originalGetSelectedCardIds = getSelectedCardIds;
function getSelectedCardIdsWithDbSelect() {
    // If Select All DB is active (via selectAllDbBtn OR selectAll checkbox), return all DB card IDs
    if (window.IDCardApp.allDbCardIds && window.IDCardApp.allDbCardIds.length > 0) {
        const selectAllDbBtn = document.getElementById('selectAllDbBtn');
        const selectAllCb = document.getElementById('selectAll');
        if ((selectAllDbBtn && selectAllDbBtn.classList.contains('active')) ||
            (selectAllCb && selectAllCb.checked)) {
            return window.IDCardApp.allDbCardIds;
        }
    }
    // Otherwise, return selected visible checkboxes
    return originalGetSelectedCardIds();
}

/**
 * Get ALL card IDs for bulk operations (download, reupload).
 * If specific rows are checked, returns those IDs (sync).
 * Otherwise, fetches ALL card IDs from the database for the current status,
 * respecting any active search/class/section filters.
 * Always returns a Promise.
 */
async function getAllCardIdsForAction() {
    // If user has explicitly selected rows (checked checkboxes), use those
    const selectedIds = getSelectedCardIdsWithDbSelect();
    if (selectedIds.length > 0) {
        return selectedIds;
    }

    // No explicit selection — fetch ALL card IDs from database (filter-aware)
    const tableId = window.IDCardApp.tableId || (typeof TABLE_ID !== 'undefined' ? TABLE_ID : null);

    if (!tableId) {
        console.error('getAllCardIdsForAction: TABLE_ID not found');
        return [];
    }

    try {
        const qs = _buildFilterQS();
        const data = await ApiClient.get(`/api/table/${tableId}/cards/all-ids/?${qs}`);
        if (data.success && data.card_ids) {
            return data.card_ids;
        }
        return [];
    } catch (error) {
        console.error('Error fetching all card IDs:', error);
        return [];
    }
}

// ==========================================
// EXPORTS
// ==========================================

window.IDCardApp.getRowCheckboxes = getRowCheckboxes;
window.IDCardApp.getSelectedCardIds = getSelectedCardIdsWithDbSelect;
window.IDCardApp.getAllVisibleCardIds = getAllVisibleCardIds;
window.IDCardApp.getCardIdsForAction = getCardIdsForAction;
window.IDCardApp.updateButtonStates = updateButtonStates;
window.IDCardApp.initCheckboxes = initCheckboxes;
window.IDCardApp.initSelectAllDbButton = initSelectAllDbButton;
window.IDCardApp.getAllCardIdsForAction = getAllCardIdsForAction;
window.IDCardApp._cacheToolbarButtons = _cacheToolbarButtons;
window.IDCardApp._buildFilterQS = _buildFilterQS;

})();


/* ── js/idcard-actions-core-init.js ── */

// ID Card Actions - Core Init Sub-module
// Contains: Sidebar, dropdowns, dynamic alignment, horizontal scroll, module init
// Split from: idcard-actions-core.js

(function() {
'use strict';

window.IDCardApp = window.IDCardApp || {};

// ==========================================
// SIDEBAR FUNCTIONALITY
// ==========================================

function initSidebar() {
    // Sidebar toggle is handled by Alpine.js layoutState() in alpine-state.js.
    // Only set the active sidebar link here — no toggle logic.
    const activeClientsLink = document.getElementById('activeClientsLink');
    const allClientsLink = document.getElementById('allClientsLink');
    if (activeClientsLink) activeClientsLink.classList.add('active');
    if (allClientsLink) allClientsLink.classList.remove('active');
}

// Expose globally
window.IDCardApp.initSidebar = initSidebar;

// ==========================================
// DROPDOWN FUNCTIONALITY
// ==========================================

function setupDropdown(dropdownId) {
    const dropdown = document.getElementById(dropdownId);
    if (!dropdown) return;
    
    const toggle = dropdown.querySelector('.dropdown-toggle');
    const options = dropdown.querySelectorAll('.dropdown-option');
    
    toggle.addEventListener('click', function(e) {
        e.stopPropagation();
        // Close other dropdowns
        document.querySelectorAll('.custom-dropdown.open').forEach(d => {
            if (d !== dropdown) d.classList.remove('open');
        });
        dropdown.classList.toggle('open');
    });
    
    options.forEach(option => {
        option.addEventListener('click', function() {
            options.forEach(o => o.classList.remove('selected'));
            this.classList.add('selected');
            
            // Update toggle text if needed
            const selectedText = toggle.querySelector('span');
            if (selectedText) {
                selectedText.textContent = this.textContent;
            }
            
            dropdown.classList.remove('open');
        });
    });
}

function initDropdowns() {
    setupDropdown('filterDropdown');
    setupDropdown('rowsDropdown');
    setupDropdown('sortDropdown');
    // classFilterDropdown and sectionFilterDropdown are handled by initFilterHandlers()
    // in idcard-actions-search.js (with event delegation for dynamic options)
    
    // Close dropdowns when clicking outside
    document.addEventListener('click', function(e) {
        // Don't close if clicking inside a dropdown
        if (e.target.closest('.custom-dropdown')) return;
        
        document.querySelectorAll('.custom-dropdown.open').forEach(d => {
            d.classList.remove('open');
        });
    });
}

// Expose globally
window.IDCardApp.setupDropdown = setupDropdown;
window.IDCardApp.initDropdowns = initDropdowns;

// ==========================================
// DYNAMIC TEXT ALIGNMENT
// ==========================================

function applyDynamicAlignment() {
    const table = document.querySelector('.idcard-table table');
    if (!table) return;
    
    const rows = table.querySelectorAll('tbody tr[data-card-id]');
    if (rows.length === 0) return;
    
    // Batch all writes in a single rAF to avoid interleaved read/write thrashing.
    // Column alignment is determined by CSS classes (get_td_width_class filter),
    // so we only need to clear stale inline overrides and center Sr No.
    requestAnimationFrame(function() {
        // Remove any stale inline textAlign so CSS classes take effect
        for (var i = 0; i < rows.length; i++) {
            var cells = rows[i].querySelectorAll('td.dynamic-field');
            for (var j = 0; j < cells.length; j++) {
                if (cells[j].style.textAlign) cells[j].style.textAlign = '';
            }
        }
        // Sr No column — center
        var srCells = document.querySelectorAll('.idcard-table td:nth-child(2)');
        for (var k = 0; k < srCells.length; k++) {
            srCells[k].style.textAlign = 'center';
        }
    });
}

// Expose on IDCardApp namespace
window.IDCardApp.applyDynamicAlignment = applyDynamicAlignment;

// ==========================================
// HORIZONTAL SCROLL WITH ALT + MOUSE WHEEL
// ==========================================

function initHorizontalScroll() {
    const tableContainer = document.querySelector('.idcard-table');
    if (tableContainer) {
        tableContainer.addEventListener('wheel', function(e) {
            // If Alt key is held, scroll horizontally
            if (e.altKey) {
                e.preventDefault();
                // Slow scroll speed - 25% for smoother scrolling
                this.scrollLeft += e.deltaY * 0.25;
            }
        }, { passive: false });
    }
}

// Expose globally
window.IDCardApp.initHorizontalScroll = initHorizontalScroll;

// ==========================================
// CORE MODULE INITIALIZATION
// ==========================================

function initCoreModule() {
    IDCardApp._cacheToolbarButtons();
    initSidebar();
    IDCardApp.initCheckboxes();
    initDropdowns();
    initHorizontalScroll();
    applyDynamicAlignment();
}

// Expose globally
window.IDCardApp.initCoreModule = initCoreModule;

})();


/* ── js/idcard-actions-table-state.js ── */

// ID Card Actions - Table State & Filters Module
// Shared state, helpers, and filter/sort functions
// Part of: idcard-actions-table split (state → render → load)

(function() {
'use strict';

// ==========================================
// SHARED STATE (used by all table sub-modules)
// ==========================================
window.IDCardApp = window.IDCardApp || {};

var _ts = {
    allRows: [],
    filteredRows: [],
    currentPage: 1,
    rowsPerPage: 100,
    currentFilter: 'all',
    currentSort: 'sr-asc',
    searchQuery: '',
    currentFilterField: 'all',
    endlessScrollMode: true,
    lazyLoadState: {
        isLoading: false,
        hasMore: false,
        totalCount: 0,
        loadedCount: 0,
        batchSize: 100,
        triggerOffset: 15,
        tableId: typeof TABLE_ID !== 'undefined' ? TABLE_ID : null,
        currentStatus: typeof CURRENT_STATUS !== 'undefined' ? CURRENT_STATUS : 'pending'
    },
    // Cleanup tracking resources
    _lazyLoadInterval: null,
    _scrollHandler: null,
    _scrollTarget: null,
    _sentinelObserver: null,
    _loadRequestSeq: 0,
    _loadCooldown: false
};

window.IDCardApp._ts = _ts;

// Expose state globally (preserves original API)
window.IDCardApp.tableState = {
    get allRows() { return _ts.allRows; },
    get filteredRows() { return _ts.filteredRows; },
    get currentPage() { return _ts.currentPage; },
    set currentPage(val) { _ts.currentPage = val; },
    get rowsPerPage() { return _ts.rowsPerPage; },
    set rowsPerPage(val) { _ts.rowsPerPage = val; },
    get searchQuery() { return _ts.searchQuery; },
    set searchQuery(val) { _ts.searchQuery = val; },
    get lazyLoadState() { return _ts.lazyLoadState; }
};

// Expose lazyLoadState directly (preserves original API)
window.IDCardApp.lazyLoadState = _ts.lazyLoadState;

// ==========================================
// INITIALIZE ROWS
// ==========================================

function initializeRows() {
    const tableBody = document.getElementById('cardsTableBody');
    if (!tableBody) return;
    _ts.allRows = Array.from(tableBody.querySelectorAll('tr[data-card-id]'));
    _ts.filteredRows = [..._ts.allRows];
}

// ==========================================
// LAZY LOAD STATE INITIALIZATION
// ==========================================

function earlyInitLazyLoadState() {
    const paginationBar = document.getElementById('paginationBar');
    if (paginationBar) {
        _ts.lazyLoadState.totalCount = parseInt(paginationBar.dataset.totalCount) || 0;
        _ts.lazyLoadState.hasMore = paginationBar.dataset.hasMore === 'true';
        _ts.lazyLoadState.loadedCount = parseInt(paginationBar.dataset.initialLoaded) || 0;
        if (!_ts.lazyLoadState.tableId && paginationBar.dataset.tableId) {
            _ts.lazyLoadState.tableId = parseInt(paginationBar.dataset.tableId);
        }
        if (paginationBar.dataset.status) {
            _ts.lazyLoadState.currentStatus = paginationBar.dataset.status;
        }
        // Disable bulk buttons early if no cards
        setTimeout(updateBulkActionButtons, 0);
    }
}

function initLazyLoadState() {
    const paginationBar = document.getElementById('paginationBar');
    if (paginationBar) {
        _ts.lazyLoadState.totalCount = parseInt(paginationBar.dataset.totalCount) || 0;
        _ts.lazyLoadState.hasMore = paginationBar.dataset.hasMore === 'true';
        // Use nullish-safe parse: parseInt("0") is 0 (falsy), so || fallback
        // would skip it. Use explicit NaN check instead.
        var _initLoaded = parseInt(paginationBar.dataset.initialLoaded);
        _ts.lazyLoadState.loadedCount = isNaN(_initLoaded) ? _ts.allRows.length : _initLoaded;
        if (!_ts.lazyLoadState.tableId && paginationBar.dataset.tableId) {
            _ts.lazyLoadState.tableId = parseInt(paginationBar.dataset.tableId);
        }
        if (paginationBar.dataset.status) {
            _ts.lazyLoadState.currentStatus = paginationBar.dataset.status;
        }
    } else {
        _ts.lazyLoadState.loadedCount = _ts.allRows.length;
        _ts.lazyLoadState.totalCount = _ts.allRows.length;
        _ts.lazyLoadState.hasMore = false;
    }
    
    window.IDCardApp.updateLazyLoadPaginationInfo();
    updateBulkActionButtons();
}

// ==========================================
// BULK ACTION BUTTONS STATE
// ==========================================

/**
 * Updates bulk action buttons (download, reupload) based on whether there are cards.
 * Disables these buttons when totalCount is 0.
 */
function updateBulkActionButtons() {
    const hasCards = _ts.lazyLoadState.totalCount > 0;
    
    // Get all bulk download/reupload buttons across all status action bars
    const bulkButtons = [
        // Pending
        'downloadImgBtn', 'downloadDocxBtn', 'downloadXlsxBtn', 'downloadPdfBtn', 'reuploadImageBtn',
        // Verified
        'downloadImgBtnV', 'downloadDocxBtnV', 'downloadXlsxBtnV', 'downloadPdfBtnV', 'reuploadImageBtnV',
        // Approved
        'downloadImgBtnA', 'downloadDocxBtnA', 'downloadXlsxBtnA', 'downloadPdfBtnA', 'reuploadImageBtnA', 'downloadCardBtn',
        // Download
        'downloadImgBtnD', 'downloadDocxBtnD', 'downloadXlsxBtnD', 'downloadPdfBtnD', 'reuploadImageBtnD',
        // Pool
        'downloadImgBtnP', 'downloadDocxBtnP', 'downloadXlsxBtnP', 'downloadPdfBtnP', 'reuploadImageBtnP'
    ];
    
    bulkButtons.forEach(btnId => {
        const btn = document.getElementById(btnId);
        if (btn) {
            btn.disabled = !hasCards;
            if (!hasCards) {
                btn.title = 'No data available';
            }
        }
    });
}

// ==========================================
// DATE/NAME/SR HELPERS
// ==========================================

function getRowDate(row) {
    const cells = row.querySelectorAll('td');
    const dateCell = cells[cells.length - 2];
    if (!dateCell) return new Date(0);
    
    const dateText = dateCell.textContent.trim();
    const parsed = Date.parse(dateText.replace(/-/g, ' '));
    return isNaN(parsed) ? new Date(0) : new Date(parsed);
}

function getRowName(row) {
    const cells = row.querySelectorAll('td');
    if (cells.length > 2) {
        return cells[2].textContent.trim().toLowerCase();
    }
    return '';
}

function getRowSrNo(row) {
    const cells = row.querySelectorAll('td');
    if (cells.length > 1) {
        return parseInt(cells[1].textContent.trim()) || 0;
    }
    return 0;
}

function getFieldColumnIndex(fieldName) {
    const headerRow = document.querySelector('.idcard-table thead tr');
    if (!headerRow) return -1;
    
    const headers = headerRow.querySelectorAll('th');
    for (let i = 0; i < headers.length; i++) {
        const headerText = headers[i].textContent.trim().toUpperCase();
        if (headerText === fieldName.toUpperCase()) {
            return i;
        }
    }
    return -1;
}

// ==========================================
// FILTER AND SORT
// ==========================================

function searchRows(query) {
    _ts.searchQuery = query.toLowerCase().trim();
    // Server-side search: reset table and reload with search param
    window.IDCardApp.resetAndReload();
}

function filterByField(fieldName) {
    _ts.currentFilterField = fieldName;
    // Field filter is client-side only — just re-run local filter on loaded rows
    applyFiltersAndSort();
}

function sortRows(sortValue) {
    _ts.currentSort = sortValue;
    // Server-side sort: reset table and reload with sort param
    window.IDCardApp.resetAndReload();
}

/**
 * Build URL query params for server-side filtering.
 * Reads current filter state from module locals + IDCardApp namespace.
 */
function _buildFilterParams() {
    var params = new URLSearchParams();
    params.set('status', _ts.lazyLoadState.currentStatus || '');
    params.set('offset', _ts.lazyLoadState.loadedCount.toString());
    params.set('limit', _ts.lazyLoadState.batchSize.toString());

    if (_ts.searchQuery) params.set('search', _ts.searchQuery);
    if (IDCardApp.currentClassFilter) params.set('class', IDCardApp.currentClassFilter);
    if (IDCardApp.currentSectionFilter) params.set('section', IDCardApp.currentSectionFilter);
    if (_ts.currentSort) params.set('sort', _ts.currentSort);
    if (IDCardApp._activeImageSort) {
        params.set('image_column', IDCardApp._activeImageSort.column || '');
        params.set('image_condition', IDCardApp._activeImageSort.condition || '');
    }
    // DateTime range (download list) — read from Flatpickr inputs
    var fromDate = document.getElementById('fromDateFilter');
    var toDate = document.getElementById('toDateFilter');
    if (fromDate && fromDate.value) params.set('from', fromDate.value);
    if (toDate && toDate.value) params.set('to', toDate.value);
    return params.toString();
}

/**
 * Client-side filter for date range only.
 * Search, class/section, image, and sort are all handled server-side now.
 * This function only applies the lightweight date filter (today/week/month)
 * on already-loaded rows.
 */
function applyFiltersAndSort() {
    var today = new Date();
    today.setHours(0, 0, 0, 0);

    var weekAgo = new Date(today);
    weekAgo.setDate(weekAgo.getDate() - 7);

    var monthAgo = new Date(today);
    monthAgo.setMonth(monthAgo.getMonth() - 1);

    var hasDateFilter = _ts.currentFilter !== 'all' && (_ts.currentFilter === 'today' || _ts.currentFilter === 'week' || _ts.currentFilter === 'month');

    if (hasDateFilter) {
        _ts.filteredRows = _ts.allRows.filter(function(row) {
            var rowDate = getRowDate(row);
            rowDate.setHours(0, 0, 0, 0);
            if (_ts.currentFilter === 'today') {
                return rowDate.getTime() === today.getTime();
            } else if (_ts.currentFilter === 'week') {
                return rowDate >= weekAgo;
            } else if (_ts.currentFilter === 'month') {
                return rowDate >= monthAgo;
            }
            return true;
        });
    } else {
        _ts.filteredRows = _ts.allRows.slice();
    }

    _ts.currentPage = 1;
    window.IDCardApp.renderTable();
}

// ==========================================
// EXPORTS
// ==========================================

// Public API (preserves original exports)
window.IDCardApp.updateBulkActionButtons = updateBulkActionButtons;
window.IDCardApp.initializeRows = initializeRows;
window.IDCardApp.searchRows = searchRows;
window.IDCardApp.filterByField = filterByField;
window.IDCardApp.sortRows = sortRows;
window.IDCardApp.applyFiltersAndSort = applyFiltersAndSort;

// Internal helpers for other table sub-modules
window.IDCardApp._earlyInitLazyLoadState = earlyInitLazyLoadState;
window.IDCardApp._initLazyLoadState = initLazyLoadState;
window.IDCardApp._buildFilterParams = _buildFilterParams;
window.IDCardApp._getRowDate = getRowDate;
window.IDCardApp._getRowName = getRowName;
window.IDCardApp._getRowSrNo = getRowSrNo;
window.IDCardApp._getFieldColumnIndex = getFieldColumnIndex;

})();


